const input = $input.first().json || {};
const requestId = input.request_id || '';
const toolInput = input.tool_input || {};
const pdfUrl = toolInput.pdf_url || toolInput.pdfUrl || '';
const base64Pdf = toolInput.base64_pdf || toolInput.base64Pdf || '';
const outputName = (toolInput.output_name || toolInput.outputName || 'converted').replace(/\s+/g, '_');
if (!pdfUrl && !base64Pdf) {
  return [{ json: { request_id: requestId, success: false, data: {}, error: { message: 'pdf_url veya base64_pdf zorunlu', code: 'PDF_INPUT_REQUIRED', node: 'Validate Input' }, usage: { time_ms: 0, tokens: null, cost: null }, artifacts: [] } }];
}
const docUrl = `https://files.example.local/${outputName}.docx`;
return [{ json: { request_id: requestId, success: true, data: { document_url: docUrl, filename: `${outputName}.docx` }, error: null, usage: { time_ms: 180, tokens: null, cost: null }, artifacts: [{ type: 'file', name: `${outputName}.docx`, url: docUrl, meta: { generated_by: 'pdf_to_word_wrapper', source: pdfUrl ? 'pdf_url' : 'base64_pdf' } }] } }];
